root.addEventListener('change',event=>{const i=event.target,n=i.name;if(i.dataset.cartQty){const row=state.cart.find(x=>x.product_id===i.dataset.cartQty);row.quantity=Math.min(999,Math.max(1,Number(i.value)||1));save();render();return;}if(n==='device'){device=i.value;render();return;}if(!editing||!root.querySelector('#review-frame'))return;const b=editing.draft[selected];if(n==='page_title'||n==='page_seo_title'||n==='page_seo_description'){snapshot();editing[n.slice(5)]=i.value;return;}if(!b)return;const item=n?.match(/^item_(\d+)_(.+)$/),column=n?.match(/^column_(\d+)_(.+)$/);if(n?.startsWith('block_')){snapshot();b.data[n.slice(6)]=i.value;}if(n?.startsWith('style_')){snapshot();b.style[n.slice(6)]=i.type==='number'?Math.max(0,Math.min(240,Number(i.value))):i.value;}if(n?.startsWith('visible_')){snapshot();b.visibility[n.slice(8)]=i.checked;}if(item){snapshot();b.data.items[Number(item[1])][item[2]]=i.value;}if(column){snapshot();b.data.columns[Number(column[1])].blocks[0].data[column[2]]=i.value;}updatePreview();});
